import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type SocialRevealProps = Record<string, any>;

const SocialReveal: React.FC<SocialRevealProps> = ({
  backgroundColor = "#f9fafb",
  transparentBackground = false,
  durationInSeconds = 5,
  facebookLogoUrl = "https://upload.wikimedia.org/wikipedia/commons/b/b8/2021_Facebook_icon.svg",
  instagramLogoUrl = "https://upload.wikimedia.org/wikipedia/commons/e/e7/Instagram_logo_2016.svg",
  logoSize = 240,
}) => {

  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const fbStartFrame = 15;
  const igStartFrame = fbStartFrame + fps; // Exactly 1 second later

  // Facebook Soft Appear Animation
  const fbOpacity = interpolate(
    frame - fbStartFrame,
    [0, 30],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.ease) }
  );
  
  const fbY = interpolate(
    frame - fbStartFrame,
    [0, 45],
    [50, 0], // Soft float up
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic) }
  );
  
  const fbScale = interpolate(
    frame - fbStartFrame,
    [0, 45],
    [0.85, 1], // Soft scale in
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic) }
  );

  // Instagram Soft Appear Animation
  const igOpacity = interpolate(
    frame - igStartFrame,
    [0, 30],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.ease) }
  );
  
  const igY = interpolate(
    frame - igStartFrame,
    [0, 45],
    [50, 0], 
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic) }
  );
  
  const igScale = interpolate(
    frame - igStartFrame,
    [0, 45],
    [0.85, 1], 
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic) }
  );

  // Layout Calculations
  // 1/3 from the left
  const fbX = (width * 0.333) - (logoSize / 2);
  // Opposite side (1/3 from the right = 2/3 from the left)
  const igX = (width * 0.667) - (logoSize / 2);
  
  const yCenter = (height * 0.5) - (logoSize / 2);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter" }}>
      
      {/* Facebook Logo Element */}
      <div
        style={{
          position: "absolute",
          left: fbX,
          top: yCenter,
          width: logoSize,
          height: logoSize,
          opacity: fbOpacity,
          transform: `translateY(${fbY}px) scale(${fbScale})`,
          transition: "none",
          display: "flex",
          justifyContent: "center",
          alignItems: "center"
        }}
      >
        <img
          src={facebookLogoUrl}
          alt="Facebook Logo"
          style={{ 
            width: "100%", 
            height: "100%", 
            objectFit: "contain", 
            transition: "none",
            filter: "drop-shadow(0px 10px 20px rgba(0,0,0,0.08))"
          }}
        />
      </div>

      {/* Instagram Logo Element */}
      <div
        style={{
          position: "absolute",
          left: igX,
          top: yCenter,
          width: logoSize,
          height: logoSize,
          opacity: igOpacity,
          transform: `translateY(${igY}px) scale(${igScale})`,
          transition: "none",
          display: "flex",
          justifyContent: "center",
          alignItems: "center"
        }}
      >
        <img
          src={instagramLogoUrl}
          alt="Instagram Logo"
          style={{ 
            width: "100%", 
            height: "100%", 
            objectFit: "contain", 
            transition: "none",
            filter: "drop-shadow(0px 10px 20px rgba(0,0,0,0.08))"
          }}
        />
      </div>

    </AbsoluteFill>
  );
};

export default SocialReveal;